program:
data {
  int<lower=1> Num;
  array[Num] int nc;
  array[Num] int nt;
  array[Num] int rc;
  array[Num] int rt;
}

parameters {
  real d;
  real<lower=0> tau;
  array[Num] real mu;
  array[Num] real delta;
  real delta_new;
}

transformed parameters {
  array[Num] real pc;
  array[Num] real pt;
  for (i in 1:Num) {
    pc[i] = inv_logit(mu[i]);
    pt[i] = inv_logit(mu[i] + delta[i]);
  }
}

model {
  d ~ normal(0.0, 1.0 / sqrt(1.0E-6));
  tau ~ gamma(0.001, 0.001);
  mu ~ normal(0.0, 1.0 / sqrt(1.0E-5));
  delta ~ normal(d, 1.0 / sqrt(tau));
  rc ~ binomial(nc, pc);
  rt ~ binomial(nt, pt);
  delta_new ~ normal(d, 1.0 / sqrt(tau));
}

generated quantities {
  real sigma;
  sigma = 1 / sqrt(tau);
}

data {
  int<lower=1> batches;
  int<lower=1> samples;
  array[batches, samples] real y;
}

parameters {
  real theta;
  real<lower=0> tau_btw;
  real<lower=0> tau_with;
  array[batches] real mu;
}

model {
  theta ~ normal(0.0, 1.0 / sqrt(1.0E-10));
  tau_btw ~ gamma(0.001, 0.001);
  tau_with ~ gamma(0.001, 0.001);
  mu ~ normal(theta, 1.0 / sqrt(tau_btw));
  for (i in 1:batches) {
    for (j in 1:samples) {
      y[i,j] ~ normal(mu[i], 1.0 / sqrt(tau_with));
    }
  }
}

generated quantities {
  real sigma2_btw;
  real sigma2_with;
  sigma2_btw = 1 / tau_btw;
  sigma2_with = 1 / tau_with;
}

data {
  int<lower=1> N;
  int<lower=1> T;
  array[N, T] int y;
  real log_Base4_bar;
  real Trt_bar;
  real BT_bar;
  real log_Age_bar;
  real V4_bar;
  array[N] real Base;
  array[N] real Trt;
  array[N] real Age;
  array[T] real V4;
}

parameters {
  real a0;
  real alpha_Base;
  real alpha_Trt;
  real alpha_BT;
  real alpha_Age;
  real alpha_V4;
  real<lower=0> tau_b1;
  real<lower=0> tau_b;
  array[N] real b1;
  array[N, T] real b;
}

transformed parameters {
  array[N, T] real mu;
  for (j in 1:N) {
    for (k in 1:T) {
      mu[j,k] = exp(a0 + alpha_Base * (log(Base[j] / 4) - log_Base4_bar) + alpha_Trt * (Trt[j] - Trt_bar) + alpha_BT * (Trt[j] * log(Base[j] / 4) - BT_bar) + alpha_Age * (log(Age[j]) - log_Age_bar) + alpha_V4 * (V4[k] - V4_bar) + b1[j] + b[j, k]);
    }
  }
}

model {
  a0 ~ normal(0.0, 1.0 / sqrt(1.0E-4));
  alpha_Base ~ normal(0.0, 1.0 / sqrt(1.0E-4));
  alpha_Trt ~ normal(0.0, 1.0 / sqrt(1.0E-4));
  alpha_BT ~ normal(0.0, 1.0 / sqrt(1.0E-4));
  alpha_Age ~ normal(0.0, 1.0 / sqrt(1.0E-4));
  alpha_V4 ~ normal(0.0, 1.0 / sqrt(1.0E-4));
  tau_b1 ~ gamma(1.0E-3, 1.0E-3);
  tau_b ~ gamma(1.0E-3, 1.0E-3);
  b1 ~ normal(0.0, 1.0 / sqrt(tau_b1));
  for (j in 1:N) {
    for (k in 1:T) {
      b[j,k] ~ normal(0.0, 1.0 / sqrt(tau_b));
      y[j,k] ~ poisson(mu[j, k]);
    }
  }
}

generated quantities {
  real alpha0;
  real sigma_b1;
  real sigma_b;
  alpha0 = a0 - alpha_Base * log_Base4_bar - alpha_Trt * Trt_bar - alpha_BT * BT_bar - alpha_Age * log_Age_bar - alpha_V4 * V4_bar;
  sigma_b1 = 1.0 / sqrt(tau_b1);
  sigma_b = 1.0 / sqrt(tau_b);
}

data {
  int<lower=1> P;
  int<lower=1> N;
  array[P] real sign;
  array[N] real group;
  array[N, P] real Y;
}

transformed data {
  array[N, P] int T;
  for (k in 1:P) {
    for (i in 1:N) {
      T[i,k] = to_int(round(group[i] * (k - 1.5) + 1.5));
    }
  }
}

parameters {
  real mu;
  real phi;
  real pi;
  real<lower=0> tau1;
  real<lower=0> tau2;
  array[N] real delta;
}

transformed parameters {
  array[N, P] real m;
  for (k in 1:P) {
    for (i in 1:N) {
      m[i,k] = mu + sign[T[i, k]] * phi / 2 + sign[k] * pi / 2 + delta[i];
    }
  }
}

model {
  mu ~ normal(0.0, 1.0 / sqrt(1.0E-6));
  phi ~ normal(0.0, 1.0 / sqrt(1.0E-6));
  pi ~ normal(0.0, 1.0 / sqrt(1.0E-6));
  tau1 ~ gamma(0.001, 0.001);
  tau2 ~ gamma(0.001, 0.001);
  for (k in 1:P) {
    for (i in 1:N) {
      Y[i,k] ~ normal(m[i, k], 1.0 / sqrt(tau1));
    }
  }
  delta ~ normal(0.0, 1.0 / sqrt(tau2));
}

generated quantities {
  real theta;
  real sigma1;
  real sigma2;
  real equiv;
  theta = exp(phi);
  sigma1 = 1 / sqrt(tau1);
  sigma2 = 1 / sqrt(tau2);
  equiv = (theta - 0.8 >= 0 ? 1 : 0) - (theta - 1.2 >= 0 ? 1 : 0);
}

data {
  int<lower=1> T;
  int<lower=1> K;
  array[T] real y;
  vector[K] pi0;
  array[K] vector[K] P;
}

parameters {
  array[K] real mu;
  real<lower=0> tau;
}

model {
  mu ~ normal(0, 1.0 / sqrt(0.01));
  tau ~ gamma(1, 1);
  // marginalize the chain z by a forward recursion
  {
    vector[K] z_lp;
    vector[K] z_lp_next;
    vector[K] z_acc;
    for (z_val in 1:K) {
      z_lp[z_val] = categorical_lpmf(z_val | pi0[1:K])
        + normal_lpdf(y[1] | mu[z_val], 1.0 / sqrt(tau));
    }
    for (t in 2:T) {
      for (z_val in 1:K) {
        for (z_prev in 1:K) {
          z_acc[z_prev] = z_lp[z_prev]
            + categorical_lpmf(z_val | P[z_prev, 1:K]);
        }
        z_lp_next[z_val] = log_sum_exp(z_acc)
          + normal_lpdf(y[t] | mu[z_val], 1.0 / sqrt(tau));
      }
      z_lp = z_lp_next;
    }
    target += log_sum_exp(z_lp);
  }
}

generated quantities {
  array[T] int z;
  // recover z by forward filtering and backward sampling
  {
    array[T] vector[K] z_fwd;
    vector[K] z_acc;
    for (z_val in 1:K) {
      z_fwd[1][z_val] = categorical_lpmf(z_val | pi0[1:K])
        + normal_lpdf(y[1] | mu[z_val], 1.0 / sqrt(tau));
    }
    for (t in 2:T) {
      for (z_val in 1:K) {
        for (z_prev in 1:K) {
          z_acc[z_prev] = z_fwd[t - 1][z_prev]
            + categorical_lpmf(z_val | P[z_prev, 1:K]);
        }
        z_fwd[t][z_val] = log_sum_exp(z_acc)
          + normal_lpdf(y[t] | mu[z_val], 1.0 / sqrt(tau));
      }
    }
    z[T] = categorical_rng(softmax(z_fwd[T]));
    for (z_rev in 1:(T - 1)) {
      int z_at = T - z_rev;
      for (z_prev in 1:K) {
        z_acc[z_prev] = z_fwd[z_at][z_prev]
          + categorical_lpmf(z[z_at + 1] | P[z_prev, 1:K]);
      }
      z[z_at] = categorical_rng(softmax(z_acc));
    }
  }
}

data {
  int<lower=1> N;
  int<lower=1> M;
  array[N] real sex;
  array[N] int disease;
  array[N, M] real age;
  array[N, M] real t;
  array[N, M] real t_cen;
  array[N, M] int t_is_obs;
}

parameters {
  real alpha;
  real beta_age;
  real beta_sex;
  real<lower=0> tau;
  real<lower=0> r;
  array[3] real beta_dis_free;
  array[N] real b;
}

transformed parameters {
  array[4] real beta_dis;
  beta_dis[1] = 0;  // placeholder: outside plate range
  beta_dis[2] = beta_dis_free[1];
  beta_dis[3] = beta_dis_free[2];
  beta_dis[4] = beta_dis_free[3];
  array[N, M] real mu;
  for (i in 1:N) {
    for (j in 1:M) {
      mu[i,j] = exp(alpha + beta_age * age[i, j] + beta_sex * sex[i] + beta_dis[disease[i]] + b[i]);
    }
  }
}

model {
  alpha ~ normal(0.0, 1.0 / sqrt(0.0001));
  beta_age ~ normal(0.0, 1.0 / sqrt(0.0001));
  beta_sex ~ normal(0.0, 1.0 / sqrt(0.0001));
  tau ~ gamma(1.0E-3, 1.0E-3);
  r ~ gamma(1.0, 1.0E-3);
  b ~ normal(0.0, 1.0 / sqrt(tau));
  for (i in 1:N) {
    for (j in 1:M) {
      if (t_is_obs[i,j] == 1) {
        t[i,j] ~ weibull(r, 1.0 / (mu[i, j]));
      } else {
        target += weibull_lccdf(t_cen[i, j] | r, 1.0 / (mu[i, j]));
      }
    }
  }
  for (k in 2:4) {
    beta_dis[k] ~ normal(0.0, 1.0 / sqrt(0.0001));
  }
}

generated quantities {
  real sigma;
  sigma = 1 / sqrt(tau);
}

data {
  int<lower=1> M;
  int<lower=1> N;
  array[M, N] real t;
  array[M, N] real t_cen;
  array[M, N] int t_is_obs;
}

parameters {
  real<lower=0.1, upper=10> r;
  array[M] real beta;
}

transformed parameters {
  array[M] real mu;
  for (i in 1:M) {
    mu[i] = exp(beta[i]);
  }
}

model {
  r ~ uniform(0.1, 10);
  beta ~ normal(0.0, 1.0 / sqrt(0.001));
  for (i in 1:M) {
    for (j in 1:N) {
      if (t_is_obs[i,j] == 1) {
        t[i,j] ~ weibull(r, 1.0 / (mu[i]));
      } else {
        target += weibull_lccdf(t_cen[i, j] | r, 1.0 / (mu[i]));
      }
    }
  }
}

generated quantities {
  array[M] real median;
  real veh_control;
  real test_sub;
  real pos_control;
  for (i in 1:M) {
    median[i] = pow(log(2) * exp(-beta[i]), 1 / r);
  }
  veh_control = beta[2] - beta[1];
  test_sub = beta[3] - beta[1];
  pos_control = beta[4] - beta[1];
}

data {
  real D;
  vector[2] piX;
  vector[2] piZ;
  array[2] real muX;
  real tauA;
  real tauB;
  real alpha0;
  real alpha1;
  array[2] real deltaC;
  array[2] real deltaZ;
  real tauD;
}

parameters {
  real A;
  real B;
}

transformed parameters {
  real pC;
  pC = inv_logit(alpha0 + alpha1 * A);
}

model {
  B ~ normal(A, 1.0 / sqrt(tauB));
  // marginalize scalar discrete latents by variable elimination
  {
    array[2] real phi_C;
    // eliminate X
    vector[2] X_lp;
    for (X_val in 1:2) {
      X_lp[X_val] = categorical_lpmf(X_val | piX[1:2])
        + normal_lpdf(A | (muX[X_val]), 1.0 / sqrt(tauA));
    }
    target += log_sum_exp(X_lp);
    // eliminate C
    for (Z_val in 1:2) {
      vector[2] C_lp;
      for (C_idx in 1:2) {
        int C_val = C_idx - 1;
        C_lp[C_idx] = bernoulli_lpmf(C_val | pC)
          + normal_lpdf(D | (B + deltaC[C_val + 1] + deltaZ[Z_val]), 1.0 / sqrt(tauD));
      }
      phi_C[Z_val] = log_sum_exp(C_lp);
    }
    // eliminate Z
    vector[2] Z_lp;
    for (Z_val in 1:2) {
      Z_lp[Z_val] = categorical_lpmf(Z_val | piZ[1:2])
        + phi_C[Z_val];
    }
    target += log_sum_exp(Z_lp);
  }
}

generated quantities {
  int Z;
  int C;
  int X;
  // recover the scalar discrete latents from their joint conditional posterior
  {
    vector[2 * 2 * 2] marg_joint_lp;
    array[2 * 2 * 2] int marg_conf_Z;
    array[2 * 2 * 2] int marg_conf_C;
    array[2 * 2 * 2] int marg_conf_X;
    int marg_c = 0;
    int marg_pick;
    for (Z_val in 1:2) {
      for (C_idx in 1:2) {
        int C_val = C_idx - 1;
        for (X_val in 1:2) {
          marg_c += 1;
          marg_joint_lp[marg_c] = categorical_lpmf(Z_val | piZ[1:2])
            + bernoulli_lpmf(C_val | pC)
            + categorical_lpmf(X_val | piX[1:2])
            + normal_lpdf(A | (muX[X_val]), 1.0 / sqrt(tauA))
            + normal_lpdf(D | (B + deltaC[C_val + 1] + deltaZ[Z_val]), 1.0 / sqrt(tauD));
          marg_conf_Z[marg_c] = Z_val;
          marg_conf_C[marg_c] = C_val;
          marg_conf_X[marg_c] = X_val;
        }
      }
    }
    marg_pick = categorical_rng(softmax(marg_joint_lp));
    Z = marg_conf_Z[marg_pick];
    C = marg_conf_C[marg_pick];
    X = marg_conf_X[marg_pick];
  }
}

data {
  int<lower=1> N;
  vector[2] w;
  array[N] real y;
}

parameters {
  array[2] real mu;
  array[2] real<lower=0> sigma;
}

model {
  mu ~ normal(0, 1.0 / sqrt(0.01));
  sigma ~ exponential(1);
  for (i in 1:N) {
    // marginalize out z[i]
    {
      vector[2] z_lp;
      for (z_val in 1:2) {
        z_lp[z_val] = categorical_lpmf(z_val | w[1:2])
          + normal_lpdf(y[i] | (mu[z_val]), 1.0 / sqrt((1 / (sigma[z_val] * sigma[z_val]))));
      }
      target += log_sum_exp(z_lp);
    }
  }
}

generated quantities {
  array[N] int z;
  // recover z from its conditional posterior
  for (i in 1:N) {
    vector[2] z_lp;
    for (z_val in 1:2) {
      z_lp[z_val] = categorical_lpmf(z_val | w[1:2])
        + normal_lpdf(y[i] | (mu[z_val]), 1.0 / sqrt((1 / (sigma[z_val] * sigma[z_val]))));
    }
    z[i] = categorical_rng(softmax(z_lp));
  }
}

data {
  int<lower=1> K;
  array[K] real year;
  array[K] int n0;
  array[K] int n1;
  array[K] int r0;
  array[K] int r1;
}

parameters {
  real alpha;
  real beta1;
  real beta2;
  real<lower=0> tau;
  array[K] real mu;
  array[K] real b;
}

transformed parameters {
  array[K] real p0;
  array[K] real logPsi;
  array[K] real p1;
  for (i in 1:K) {
    p0[i] = inv_logit(mu[i]);
    logPsi[i] = alpha + beta1 * year[i] + beta2 * (year[i] * year[i] - 22) + b[i];
    p1[i] = inv_logit(mu[i] + logPsi[i]);
  }
}

model {
  alpha ~ normal(0.0, 1.0 / sqrt(1.0E-6));
  beta1 ~ normal(0.0, 1.0 / sqrt(1.0E-6));
  beta2 ~ normal(0.0, 1.0 / sqrt(1.0E-6));
  tau ~ gamma(0.001, 0.001);
  mu ~ normal(0.0, 1.0 / sqrt(1.0E-6));
  b ~ normal(0, 1.0 / sqrt(tau));
  r0 ~ binomial(n0, p0);
  r1 ~ binomial(n1, p1);
}

generated quantities {
  real sigma;
  sigma = 1 / sqrt(tau);
}

data {
  int<lower=1> N;
  array[N] real t;
  array[N] int x;
}

parameters {
  real<lower=0> alpha;
  real<lower=0> beta;
  array[N] real<lower=0> theta;
}

transformed parameters {
  array[N] real lambda;
  for (i in 1:N) {
    lambda[i] = theta[i] * t[i];
  }
}

model {
  alpha ~ exponential(1);
  beta ~ gamma(0.1, 1.0);
  theta ~ gamma(alpha, beta);
  x ~ poisson(lambda);
}

data {
  int<lower=1> N;
  int<lower=1> T;
  array[T] real x;
  real xbar;
  array[N, T] real Y;
}

parameters {
  real<lower=0> tau_c;
  real alpha_c;
  real<lower=0> alpha_tau;
  real beta_c;
  real<lower=0> beta_tau;
  array[N] real alpha;
  array[N] real beta;
}

transformed parameters {
  array[N, T] real mu;
  for (i in 1:N) {
    for (j in 1:T) {
      mu[i,j] = alpha[i] + beta[i] * (x[j] - xbar);
    }
  }
}

model {
  alpha ~ normal(alpha_c, 1.0 / sqrt(alpha_tau));
  beta ~ normal(beta_c, 1.0 / sqrt(beta_tau));
  for (i in 1:N) {
    for (j in 1:T) {
      Y[i,j] ~ normal(mu[i,j], 1.0 / sqrt(tau_c));
    }
  }
  tau_c ~ gamma(0.001, 0.001);
  alpha_c ~ normal(0.0, 1.0 / sqrt(1.0E-6));
  alpha_tau ~ gamma(0.001, 0.001);
  beta_c ~ normal(0.0, 1.0 / sqrt(1.0E-6));
  beta_tau ~ gamma(0.001, 0.001);
}

generated quantities {
  real sigma;
  real alpha0;
  sigma = 1 / sqrt(tau_c);
  alpha0 = alpha_c - xbar * beta_c;
}

data {
  int<lower=1> doses;
  int<lower=1> plates;
  array[doses] real x;
  array[doses, plates] int y;
}

parameters {
  real alpha;
  real beta;
  real gamma;
  real<lower=0> tau;
  array[doses, plates] real lambda;
}

transformed parameters {
  array[doses, plates] real mu;
  for (i in 1:doses) {
    for (j in 1:plates) {
      mu[i,j] = exp(alpha + beta * log(x[i] + 10) + gamma * x[i] + lambda[i, j]);
    }
  }
}

model {
  alpha ~ normal(0.0, 1.0 / sqrt(1.0E-6));
  beta ~ normal(0.0, 1.0 / sqrt(1.0E-6));
  gamma ~ normal(0.0, 1.0 / sqrt(1.0E-6));
  tau ~ gamma(0.001, 0.001);
  for (i in 1:doses) {
    for (j in 1:plates) {
      lambda[i,j] ~ normal(0.0, 1.0 / sqrt(tau));
      y[i,j] ~ poisson(mu[i, j]);
    }
  }
}

generated quantities {
  real sigma;
  sigma = 1 / sqrt(tau);
}

data {
  int<lower=1> N;
  array[N] real x1;
  array[N] real x2;
  array[N] int n;
  array[N] int r;
}

parameters {
  real alpha0;
  real alpha1;
  real alpha2;
  real alpha12;
  real<lower=0> tau;
  array[N] real b;
}

transformed parameters {
  array[N] real p;
  for (i in 1:N) {
    p[i] = inv_logit(alpha0 + alpha1 * x1[i] + alpha2 * x2[i] + alpha12 * x1[i] * x2[i] + b[i]);
  }
}

model {
  alpha0 ~ normal(0.0, 1.0 / sqrt(1.0E-6));
  alpha1 ~ normal(0.0, 1.0 / sqrt(1.0E-6));
  alpha2 ~ normal(0.0, 1.0 / sqrt(1.0E-6));
  alpha12 ~ normal(0.0, 1.0 / sqrt(1.0E-6));
  tau ~ gamma(0.001, 0.001);
  b ~ normal(0.0, 1.0 / sqrt(tau));
  r ~ binomial(n, p);
}

generated quantities {
  real sigma;
  sigma = 1 / sqrt(tau);
}

