  int<lower=1> N;
  array[N] int n;
  array[N] int r;
}

parameters {
  array[N] real<lower=0, upper=1> p;
}

model {
  p ~ beta(1.0, 1.0);
  r ~ binomial(n, p);
}

data {
  int<lower=1> J;
  array[J] real y;
  array[J] real<lower=0> sigma;
}
parameters {
  real mu;
  real<lower=0> tau;
  array[J] real theta;
}
model {
  mu ~ normal(0, 5);
  tau ~ cauchy(0, 5);
  theta ~ normal(mu, tau);
  y ~ normal(theta, sigma);
}
generated quantities {
  array[J] real y_rep;
  for (j in 1:J) {
    y_rep[j] = normal_rng(theta[j], sigma[j]);
  }
}

data { int<lower=0> N; int<lower=1> K; array[N] real y; array[N] int<lower=1,upper=K> g; vector[N] x; }
parameters { real mu; real<lower=0> sigma; vector[K] a; }
transformed parameters { vector[N] m; for (n in 1:N) { m[n] = mu + a[g[n]] * x[n]; } }
model {
  mu ~ normal(0, 10);
  a ~ normal(0, sigma);
  for (n in 1:N) { y[n] ~ normal(m[n], sigma); }
  target += -0.5 * square(sigma);
}
generated quantities { real s2 = sigma^2; }
